:root {
--bg: #0b0c10;
--panel: #12141a;
--panel-2: #171a21;
--panel-3: #1b1e27;
--border: #242732;
--border-soft: #1d2029;
--text: #f4f5f7;
--text-muted: #9296a1;
--text-dim: #5c616e;
--purple: #5b4cf5;
--purple-soft: rgba(91, 76, 245, 0.12);
--green: #22c55e;
--green-soft: rgba(34, 197, 94, 0.12);
--amber: #f5b942;
}

* {
box-sizing: border-box;
}

body {
background: var(--bg);
color: var(--text);
font-family: 'Inter', sans-serif;
font-size: 14px;
}

a {
text-decoration: none;
}

/* ---------- Navbar ---------- */
.navbar-custom {
background: var(--panel);
border-bottom: 1px solid var(--border-soft);
padding: 0.85rem 1.5rem;
}

.brand-icon {
width: 36px;
height: 36px;
border-radius: 9px;
background: linear-gradient(135deg, #8b5cf6, #4a3de0);
display: flex;
align-items: center;
justify-content: center;
font-weight: 800;
font-size: 1rem;
flex-shrink: 0;
}

.brand-name {
font-weight: 700;
font-size: 1.05rem;
color: var(--text);
}

.nav-item-top {
color: var(--text-muted);
font-weight: 600;
font-size: 0.9rem;
padding: 0.4rem 0.2rem;
position: relative;
}

.nav-item-top.active {
color: var(--text);
}

.nav-item-top.active::after {
content: "";
position: absolute;
left: 0;
right: 0;
bottom: -14px;
height: 2px;
background: var(--purple);
border-radius: 2px;
}

.search-box {
background: var(--panel-2);
border: 1px solid var(--border);
border-radius: 10px;
padding: 0.5rem 0.9rem;
display: flex;
align-items: center;
gap: 0.6rem;
color: var(--text-dim);
flex-grow: 1;
max-width: 460px;
}

.search-box input {
background: transparent;
border: none;
outline: none;
color: var(--text);
font-size: 0.85rem;
width: 100%;
}

.search-box input::placeholder {
color: var(--text-dim);
}

.topbar-balance {
background: var(--panel-2);
border: 1px solid var(--border-soft);
border-radius: 10px;
padding: 0.35rem 0.8rem;
display: flex;
align-items: center;
gap: 0.6rem;
}

.balance-label {
font-size: 0.68rem;
color: var(--text-dim);
}

.balance-amount {
font-weight: 700;
color: var(--green);
font-size: 0.95rem;
}

.plus-btn {
width: 26px;
height: 26px;
border-radius: 7px;
background: var(--purple);
display: flex;
align-items: center;
justify-content: center;
color: #fff;
border: none;
font-size: 0.7rem;
}

.avatar-circle {
width: 34px;
height: 34px;
border-radius: 50%;
background: var(--purple);
display: flex;
align-items: center;
justify-content: center;
font-weight: 700;
color: #fff;
font-size: 0.85rem;
flex-shrink: 0;
}

/* ---------- Hero ---------- */
.hero {
background: radial-gradient(ellipse at top left, rgba(91, 76, 245, 0.15), transparent 55%), var(--bg);
padding: 2.5rem 1.5rem 1.5rem;
}

.hero-inner {
max-width: 1400px;
margin: 0 auto;
}

.hero-title {
font-weight: 900;
font-size: 2.4rem;
letter-spacing: -0.02em;
}

.hero-sub {
color: var(--text-dim);
font-size: 1rem;
margin-top: 0.3rem;
}

/* ---------- Category pills ---------- */
.cat-scroll {
overflow-x: auto;
padding-bottom: 2px;
}

.cat-scroll::-webkit-scrollbar {
height: 0;
}

.cat-pill {
display: flex;
align-items: center;
gap: 0.5rem;
background: var(--panel);
border: 1px solid var(--border-soft);
color: var(--text-muted);
font-weight: 600;
font-size: 0.85rem;
padding: 0.6rem 1.1rem;
border-radius: 10px;
white-space: nowrap;
flex-shrink: 0;
}

.cat-pill.active {
background: var(--purple);
border-color: var(--purple);
color: #fff;
}

.cat-pill:hover:not(.active) {
background: var(--panel-2);
color: var(--text);
}

/* ---------- Content wrap ---------- */
.page-wrap {
padding: 1.5rem;
max-width: 1400px;
margin: 0 auto;
}

.results-label {
color: var(--text-muted);
font-size: 0.9rem;
}

.filter-btn {
background: var(--panel);
border: 1px solid var(--border-soft);
color: var(--text-muted);
font-size: 0.83rem;
font-weight: 500;
padding: 0.5rem 0.9rem;
border-radius: 9px;
display: flex;
align-items: center;
gap: 0.5rem;
white-space: nowrap;
}

.filter-btn:hover {
background: var(--panel-2);
color: var(--text);
}

.filter-btn.filters-main {
background: var(--panel-2);
color: var(--text);
}

/* ---------- Product Card ---------- */
.product-card {
background: var(--panel);
border: 1px solid var(--border-soft);
border-radius: 14px;
padding: 1.1rem;
height: 100%;
display: flex;
flex-direction: column;
}

.product-card:hover {
border-color: #33384a;
}

.card-top {
display: flex;
gap: 0.85rem;
margin-bottom: 0.85rem;
}

.product-thumb {
width: 64px;
height: 64px;
border-radius: 12px;
display: flex;
align-items: center;
justify-content: center;
flex-shrink: 0;
font-size: 1.6rem;
color: #fff;
}

.card-cat {
font-size: 0.72rem;
color: var(--text-dim);
margin-bottom: 0.15rem;
}

.card-title {
font-weight: 700;
font-size: 1.02rem;
line-height: 1.25;
}

.badge-stock {
background: var(--green-soft);
color: var(--green);
border: 1px solid rgba(34, 197, 94, 0.3);
font-weight: 600;
font-size: 0.68rem;
padding: 0.25rem 0.55rem;
border-radius: 6px;
white-space: nowrap;
height: fit-content;
}

.badge-stock-out {
background: rgba(239, 68, 68, 0.1);
color: #ef4444;
border: 1px solid rgba(239, 68, 68, 0.3);
font-weight: 600;
font-size: 0.68rem;
padding: 0.25rem 0.55rem;
border-radius: 6px;
white-space: nowrap;
height: fit-content;
}

.card-desc {
font-size: 0.78rem;
color: var(--text-dim);
line-height: 1.5;
margin-bottom: 0.75rem;
height: 3em;
display: -webkit-box;
-webkit-line-clamp: 2;
-webkit-box-orient: vertical;
overflow: hidden;
}

.tag-chip {
background: var(--panel-2);
border: 1px solid var(--border);
color: var(--text-muted);
font-size: 0.7rem;
padding: 0.22rem 0.55rem;
border-radius: 6px;
}

.card-rating {
font-size: 0.78rem;
color: var(--text-muted);
margin: 0.7rem 0 0.5rem;
}

